#include "gtest/gtest.h"
#include "PIMBlock.h"
#include <cmath>
using namespace DRAMSim;
namespace{enum class Op{ADD,MUL,MAC,MAD};void run(PIMBlock&b,Op o,BurstType&d,const BurstType&a,const BurstType&x,const BurstType&c,uint32_t n){if(o==Op::ADD)b.add(d,a,x,n);else if(o==Op::MUL)b.mul(d,a,x,n);else if(o==Op::MAC)b.mac(d,a,x,n);else b.mad(d,a,x,c,n);}float want(Op o,float a,float b,float d,float c){if(o==Op::ADD)return a+b;if(o==Op::MUL)return a*b;if(o==Op::MAC)return a*b+d;return a*b+c;}void check(Op o){for(uint32_t n:{0u,1u,3u,5u,7u,8u}){PIMBlock p(FP32);BurstType a,b,c,d;for(uint32_t i=0;i<8;i++){a.fp32Data_[i]=i<n?i+1:NAN;b.fp32Data_[i]=i<n?i+2:INFINITY;c.fp32Data_[i]=i<n?20+i:-INFINITY;d.fp32Data_[i]=100+i;}BurstType old=d;run(p,o,d,a,b,c,n);for(uint32_t i=0;i<8;i++)if(i<n)EXPECT_FLOAT_EQ(d.fp32Data_[i],want(o,a.fp32Data_[i],b.fp32Data_[i],old.fp32Data_[i],c.fp32Data_[i]));else EXPECT_FLOAT_EQ(d.fp32Data_[i],old.fp32Data_[i]);auto&s=p.simdCounters();EXPECT_EQ(s.active_lanes,n);EXPECT_EQ(s.masked_lanes,8-n);EXPECT_EQ(s.invalid_lane_operand_reads+s.invalid_lane_arithmetic_operations+s.invalid_lane_destination_writes+s.invalid_lane_partial_results,0);}}}
TEST(CSCFP32MaskedSIMDTest,ADD){check(Op::ADD);}TEST(CSCFP32MaskedSIMDTest,MUL){check(Op::MUL);}TEST(CSCFP32MaskedSIMDTest,MAC){check(Op::MAC);}TEST(CSCFP32MaskedSIMDTest,MAD){check(Op::MAD);}TEST(CSCFP32MaskedSIMDTest,InvalidCount){PIMBlock p(FP32);BurstType a,b,d;EXPECT_THROW(p.mul(d,a,b,9),std::invalid_argument);}
